style.css:
@-moz-document domain("roblox.com") {
/* Main Background - The Void */
    body, .content, .rbx-header {
        background-color: #1a1a2e !important;
        color: #ffffff !important;
    }

    /* Astro's Indigo Panels */
    .section-content, .item-card-container, .menu-sidebar-container {
        background-color: #4b0082 !important;
        border-radius: 12px;
        border: 1px solid #87ceeb !important; /* Aqua glow border */
    }

    /* Buttons - Aqua Blue Glow */
    .btn-primary-md, .btn-growth-md {
        background-color: #87ceeb !important;
        border: none !important;
        box-shadow: 0 0 10px #87ceeb;
        color: #1a1a2e !important;
        font-weight: bold;
    }

    /* Moonlight Hover Effects */
    .item-card-container:hover {
        transform: scale(1.05);
        box-shadow: 0 0 15px #fffacd !important;
        transition: 0.3s;
    }

    /* Custom Cursor Idea */
    * {
        cursor: url('https://cursors-4u.net'), auto !important;
    }
}
